mapper.select:
SELECT x.* FROM () x WHERE 1=1 
ORDER BY x.occurred_at DESC NULLS LAST,x.source_kind,x.source_numeric_id
LIMIT #{limit} OFFSET #{offset}

SELECT r.* FROM

	mom_mes.mes_ng_material_policy_operation
	mom_mes.mes_production_material_operation
	mom_mes.mes_production_feed_batch
	mom_mes.mes_task_report
 r
WHERE r.tenant_id=#{tenant} AND r.factory_code=#{factory} AND r.id=#{rootId}
AND r.task_code=#{task} AND r.arrange_code=#{arrange}
AND r.produce_task_code=#{produce} AND r.request_id=#{request}

SELECT r.* FROM

	mom_mes.mes_warehouse_live_stock
	mom_mes.mes_warehouse_feed
 r
WHERE r.tenant_id=#{tenant} AND r.factory_code=#{factory} AND r.mat_code=#{material}

	AND r.id=#{stockId}
	AND r.id=#{feedId} AND r.task_code=#{task} AND r.arrange_code=#{arrange}

choose.when:
SELECT r.* FROM mom_mes.mes_ng_material_policy_restore r
WHERE r.tenant_id=#{tenant} AND r.factory_code=#{factory} AND r.operation_id=#{rootId}
AND r.allocation_id=#{id} ORDER BY r.id

SELECT r.* FROM mom_mes.mes_production_feed_restore_line r
WHERE r.tenant_id=#{tenant} AND r.factory_code=#{factory} AND r.batch_id=#{rootId}
AND r.consumption_id=#{id} AND r.feed_id=#{feedId} ORDER BY r.id

SELECT r.* FROM mom_mes.mes_production_material_restore r
WHERE r.tenant_id=#{tenant} AND r.factory_code=#{factory} AND r.operation_id=#{rootId}
AND r.feed_id=#{feedId} ORDER BY r.id

choose.otherwise:
SELECT c.* FROM mom_mes.mes_report_material_consume c
WHERE c.tenant_id=#{tenant} AND c.factory_code=#{factory} AND c.id=#{id}
AND c.report_id=#{rootId} AND c.arrange_code=#{arrange} AND c.reverse_request_id IS NOT NULL

choose.when:
SELECT r.* FROM mom_mes.mes_production_material_reversal r
WHERE r.tenant_id=#{tenant} AND r.factory_code=#{factory} AND r.operation_id=#{rootId}
AND r.source_unqualified_report_id=#{reportId}
AND EXISTS(SELECT 1 FROM mom_mes.mes_production_material_restore l
WHERE l.reversal_id=r.id AND l.tenant_id=r.tenant_id AND l.factory_code=r.factory_code
AND l.operation_id=r.operation_id AND l.feed_id=#{feedId}) ORDER BY r.id

choose.otherwise:
SELECT DISTINCT r.* FROM mom_mes.mes_report_reverse_request r
JOIN mom_mes.mes_report_quantity_correction_line l ON l.reverse_request_id=r.id
AND l.tenant_id=r.tenant_id AND l.factory_code=r.factory_code AND l.report_id=r.report_id
WHERE r.tenant_id=#{tenant} AND r.factory_code=#{factory} AND r.report_id=#{rootId}
AND r.task_code=#{task} AND r.arrange_code=#{arrange} AND r.produce_task_code=#{produce}
AND l.source_id=#{id}

	AND l.allocation_type='MATERIAL_CONSUME'
	AND l.allocation_type='MATERIAL_FLOW'

ORDER BY r.id

mapper.select:
SELECT l.* FROM mom_mes.mes_report_quantity_correction_line l WHERE l.tenant_id=#{tenant} AND l.factory_code=#{factory} AND l.report_id=#{rootId} AND l.source_id=#{id}
AND l.allocation_type='MATERIAL_CONSUME' AND l.allocation_type='MATERIAL_FLOW'
ORDER BY l.id
